package com.jetbrains.mpsext.richtext.styles.util;

/*Generated by MPS */

import org.jetbrains.annotations.Nullable;
import java.awt.Color;
import com.intellij.ui.ColorUtil;
import org.jetbrains.annotations.NotNull;

/**
 * An utility class that provides methods to convert color values.
 * 
 * @author Venkat Prithvi.
 */
public class RichtextColorUtil {
  private RichtextColorUtil() {
    // utility class, should not be instantiated.
  }
  /**
   * Converts rich-text color value into an AWT color.
   * 
   * @param value color value in either #RRGGBB format or #RRGGBBAA format
   * @return the corresponding AWT color or null for an empty or invalid value
   */
  @Nullable
  public static Color toAwtColor(@Nullable String value) {
    if ((value == null || value.length() == 0)) {
      return null;
    }
    String hex = (value.startsWith("#") ? value.substring(1) : value);
    try {
      if (hex.length() == 6) {
        return ColorUtil.fromHex(hex, null);
      }
      if (hex.length() == 8) {
        Color rgb = ColorUtil.fromHex(hex.substring(0, 6), null);
        if (rgb == null) {
          return null;
        }
        int alpha = Integer.parseInt(hex.substring(6), 16);
        return ColorUtil.toAlpha(rgb, alpha);
      }
    } catch (IllegalArgumentException ignored) {
      return null;
    }
    return null;
  }

  /**
   * Converts an AWT color into the rich-text color representation
   * 
   * Opaque colors are stored as #RRGGBB and colors with transparency are stored as RRGGBBAA
   * 
   * @param color AWT color
   * @return rich-text color value
   */
  public static String toModelValue(@NotNull Color color) {
    return "#" + ColorUtil.toHex(color, color.getAlpha() != 255);
  }

}
